'use strict';
(()=>{
 let scene,camera,renderer,root,canvas,world,finish,leaderHud,viewHud,state=null,players=[],strips=[],streams=[],shape='',failed=false,last=0,scroll=0,curvePhase=0,roadWidth=14,mode='chase',forced=null,shotUntil=0,lastShot=-100,leaderId=null;
 const point=new THREE.Vector3(),look=new THREE.Vector3(),eye=new THREE.Vector3(),dummy=new THREE.Object3D();
 const orbit={angle:0,height:8,radius:17};
 const shots={chase:{angle:0,height:8,radius:17},front:{angle:Math.PI,height:6.7,radius:17},overhead:{angle:.06,height:24,radius:5},corner:{angle:.68,height:11,radius:18}};
 const mat=(c,metal=.3,rough=.4)=>new THREE.MeshStandardMaterial({color:c,metalness:metal,roughness:rough});
 function mesh(g,m,x=0,y=0,z=0){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);return o}
 const box=(w,h,d,m,x=0,y=0,z=0)=>mesh(new THREE.BoxGeometry(w,h,d),m,x,y,z);
 function swept(sections,m){const positions=[],indices=[];for(const [z,w,h,b=.24]of sections){for(const [x,y]of [[-.85*w,b],[.85*w,b],[w,.39],[.95*w,h],[.6*w,h+.035],[-.6*w,h+.035],[-.95*w,h],[-w,.39]])positions.push(x,y,z)}for(let n=0;n<sections.length-1;n++)for(let k=0;k<8;k++){const a=n*8+k,b=n*8+(k+1)%8,c=a+8,d=b+8;indices.push(a,b,c,b,d,c)}for(let k=1;k<7;k++){indices.push(0,k+1,k);const end=(sections.length-1)*8;indices.push(end,end+k,end+k+1)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setIndex(indices);g.computeVertexNormals();return mesh(g,m)}
 function numberDecal(n){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');x.fillStyle='#f4fafb';x.beginPath();x.arc(64,64,55,0,Math.PI*2);x.fill();x.fillStyle='#071626';x.font='900 84px Arial';x.textAlign='center';x.textBaseline='middle';x.fillText(String(n),64,69);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const decal=mesh(new THREE.PlaneGeometry(.58,.58),new THREE.MeshBasicMaterial({map:tex,transparent:true}),0,.715,-1.02);decal.rotation.x=-Math.PI/2;return decal}
 function createCar(style,index){const group=new THREE.Group(),paint=new THREE.MeshPhysicalMaterial({color:style.color,metalness:.55,roughness:.25,clearcoat:1,clearcoatRoughness:.15}),black=mat('#07121a',.3,.35),rubber=mat('#090c11',.05,.9),glass=new THREE.MeshPhysicalMaterial({color:'#244a61',metalness:.65,roughness:.18,clearcoat:1}),alloy=mat('#c8e0ee',.8,.2),stripe=mat('#edf8fb',.4,.3),model=style.model||'gt';
  const bodySections=model==='formula'?[[-1.85,.36,.43],[-1.25,.48,.53],[-.45,.9,.64],[.9,.88,.66],[1.65,.72,.5]]:[[-1.7,.71,.48],[-1.42,.94,.6],[-.55,.97,.69],[.72,.98,.68],[1.45,.92,.6],[1.7,.78,.51]];
  group.add(swept(bodySections,paint),box(1.92,.12,3.05,black,0,.26,0));
  if(model==='formula'){group.add(swept([[-.52,.35,.68],[0,.40,1.0],[.55,.42,.98],[.95,.6,.67]],glass));group.add(box(.22,.035,2.35,stripe,0,.71,-.15),box(2.30,.10,.43,paint,0,.35,-1.82));}else{group.add(swept([[-.72,.73,.69],[-.24,.65,1.12],[.54,.69,1.12],[1.03,.81,.72]],glass));group.add(box(1.12,.045,.77,paint,0,1.16,.17),box(.19,.025,.83,stripe,0,.70,-1.04),box(.19,.03,.75,stripe,0,1.19,.17));for(const x of [-.76,.76])group.add(box(.07,.30,.08,paint,x,.87,.62))}
  const tires=[];for(const x of [-1.02,1.02])for(const z of [-1.02,1.03]){const wheel=new THREE.Group();wheel.position.set(x,.38,z);const t=mesh(new THREE.CylinderGeometry(.39,.39,.33,20),rubber);t.rotation.z=Math.PI/2;const rim=mesh(new THREE.CylinderGeometry(.25,.25,.35,16),alloy);rim.rotation.z=Math.PI/2;wheel.add(t,rim);for(let i=0;i<5;i++){const spoke=box(.37,.055,.43,black);spoke.rotation.x=i*Math.PI/5;wheel.add(spoke)}group.add(wheel);tires.push(wheel)}
  group.add(box(2.15,.10,.43,black,0,1.13,1.43));for(const x of [-.68,.68])group.add(box(.09,.43,.12,black,x,.89,1.4));
  group.add(box(1.35,.18,.07,black,0,.41,-1.68),box(2.06,.07,.3,black,0,.26,-1.73));
  const red=new THREE.MeshBasicMaterial({color:'#ff3152'}),white=new THREE.MeshBasicMaterial({color:'#d8ffff'});for(const x of [-.60,.60]){group.add(box(.46,.10,.05,red,x,.58,1.67),box(.38,.12,.06,white,x,.57,-1.59),box(.14,.06,.3,black,x,.73,-.91),box(.15,.09,.14,alloy,x,.3,1.73))}
  group.add(numberDecal(index+1));const shadow=mesh(new THREE.PlaneGeometry(2.6,4.1),new THREE.MeshBasicMaterial({color:'#000000',transparent:true,opacity:.45,depthWrite:false}),0,.015,0);shadow.rotation.x=-Math.PI/2;group.add(shadow);group.scale.setScalar(1.15);
  const label=document.createElement('div');label.className='race3d-profile';label.style.setProperty('--car',style.color);label.innerHTML='<span class="race3d-number"></span><img alt=""><span class="race3d-initial"></span><span class="race3d-flag"></span>';root.append(label);
  return {group,tires,label,index,distance:null,velocity:0,key:''};
 }
 function centerAt(z){return Math.sin(z*.035+curvePhase)*6.5}
 function slopeAt(z){return Math.cos(z*.035+curvePhase)*.2275}
 function strip(width,offset,material,y=0){const g=new THREE.BufferGeometry(),array=new Float32Array(122*3),indices=[];for(let i=0;i<60;i++){const n=i*2;indices.push(n,n+2,n+1,n+1,n+2,n+3)}g.setAttribute('position',new THREE.BufferAttribute(array,3));g.setIndex(indices);g.computeVertexNormals();const o=mesh(g,material);world.add(o);strips.push({mesh:o,width,offset,y});return o}
 function instance(material,records){const o=new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1),material,records.length);o.instanceMatrix.setUsage(THREE.DynamicDrawUsage);o.frustumCulled=false;for(let i=0;i<records.length;i++)if(records[i].color)o.setColorAt(i,new THREE.Color(records[i].color));world.add(o);streams.push({mesh:o,records})}
 function dispose(o){const geometries=new Set(),materials=new Set();o.traverse(x=>{if(x.geometry)geometries.add(x.geometry);for(const m of Array.isArray(x.material)?x.material:x.material?[x.material]:[])materials.add(m)});geometries.forEach(g=>g.dispose());materials.forEach(m=>{m.map?.dispose();m.dispose()})}
 function init(){if(failed||renderer)return !!renderer;try{root=document.createElement('div');root.id='race3d';root.setAttribute('aria-label','Three-dimensional racing camera');document.getElementById('track').append(root);renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.4;canvas=renderer.domElement;root.prepend(canvas);leaderHud=document.createElement('div');leaderHud.className='race3d-leader';viewHud=document.createElement('div');viewHud.className='race3d-camera';root.append(leaderHud,viewHud);scene=new THREE.Scene();scene.background=new THREE.Color('#0c2031');scene.fog=new THREE.Fog('#0c2031',55,125);camera=new THREE.PerspectiveCamera(48,1,.1,240);scene.add(new THREE.HemisphereLight('#dcf4ff','#586169',2.6));const sun=new THREE.DirectionalLight('#fff5dc',3.2);sun.position.set(-14,25,12);scene.add(sun);const fill=new THREE.DirectionalLight('#83dfff',1.7);fill.position.set(12,10,-18);scene.add(fill);world=new THREE.Group();scene.add(world);document.body.classList.add('scene3d-active');canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();document.body.classList.remove('scene3d-active')});requestAnimationFrame(draw);return true}catch{failed=true;root?.remove();document.body.classList.remove('scene3d-active');return false}}
 function rebuild(){for(const p of players){p.label.remove();scene.remove(p.group);dispose(p.group)}players=[];dispose(world);world.clear();strips=[];streams=[];roadWidth=state.settings.cars*3.2+1.2;world.add(box(350,.1,300,mat('#163331',0,1),0,-.3,0));strip(roadWidth,0,mat('#34404d',.1,.83));for(const side of [-1,1])strip(.32,side*(roadWidth/2+.2),new THREE.MeshBasicMaterial({color:'#9ce2e6'}),.04);
  const marks=[],curbs=[],posts=[],lamps=[],buildings=[],windows=[];for(let z=-90;z<90;z+=7){for(let lane=1;lane<state.settings.cars;lane++)marks.push({x:(lane-state.settings.cars/2)*3.2,z,y:.025,scale:[.10,.025,3.2]});for(const side of [-1,1])curbs.push({x:side*(roadWidth/2+.2),z,y:.08,scale:[.38,.10,2.1],color:Math.round(z/7)%2?'#eb6574':'#eef9f6'})}
  for(let z=-90;z<90;z+=15)for(const side of [-1,1]){const x=side*(roadWidth/2+1.3),height=5+Math.abs(z)%10;posts.push({x,z,y:1.7,scale:[.11,3.4,.11]});lamps.push({x,z,y:3.4,scale:[1,.11,.35]});buildings.push({x:side*(roadWidth/2+6),z:z+3,y:height/2-.1,scale:[3.5,height,5],color:side<0?'#2d526a':'#38516b'});for(let row=1;row<3;row++)windows.push({x:side*(roadWidth/2+4.22),z:z+3,y:row*height/3,scale:[.035,.18,3.5]})}
  instance(new THREE.MeshBasicMaterial({color:'#f1faf6'}),marks);instance(mat('#ffffff',.2,.6),curbs);instance(mat('#708898',.65,.3),posts);instance(new THREE.MeshBasicMaterial({color:'#a3ecff'}),lamps);instance(mat('#ffffff',.3,.6),buildings);instance(new THREE.MeshBasicMaterial({color:'#54b9db'}),windows);
  finish=new THREE.Group();for(let row=0;row<2;row++)for(let col=0;col<state.settings.cars*4;col++){const size=roadWidth/(state.settings.cars*4);finish.add(box(size,.03,.62,new THREE.MeshBasicMaterial({color:(row+col)%2?'#07111a':'#eefcfe'}),-roadWidth/2+(col+.5)*size,.04,row*.62))}world.add(finish);
  for(let i=0;i<state.settings.cars;i++){const p=createCar(state.carStyles?.[i]||{color:['#ffc857','#58d9ff','#ff5c83','#71edb1','#bf94ff'][i]},i);scene.add(p.group);players.push(p)}
 }
 function resize(){if(!renderer)return;const track=document.getElementById('track'),r=track.querySelector('.road')?.getBoundingClientRect(),b=track.getBoundingClientRect();if(!r||!b.width||!r.height)return;root.style.top=(r.top-b.top)+'px';root.style.height=r.height+'px';if(canvas.clientWidth!==Math.round(b.width)||canvas.clientHeight!==Math.round(r.height))renderer.setSize(b.width,r.height);camera.aspect=b.width/r.height;camera.updateProjectionMatrix()}
 function update(r){state=r;if(!document.body.classList.contains('screen')||!init())return;const key=JSON.stringify([r.settings.cars,r.carStyles]);if(key!==shape){shape=key;rebuild()}for(const [i,p]of players.entries()){const driver=r.slots[i],key=JSON.stringify([driver?.id,driver?.avatar,driver?.name,driver?.countryFlag]);if(key!==p.key){p.key=key;p.label.querySelector('.race3d-number').textContent=String(i+1);const image=p.label.querySelector('img');image.hidden=!driver?.avatar;if(driver?.avatar)image.src=driver.avatar;p.label.querySelector('.race3d-initial').textContent=driver?.avatar?'':(driver?.name||'CAR').slice(0,1);p.label.querySelector('.race3d-flag').textContent=driver?.countryFlag||'';p.label.title=driver?.name||'OPEN SLOT'}p.group.visible=!!driver;p.label.hidden=!driver}resize()}
 function chooseCamera(elapsed,running,t,leader,fast){if(forced&&t<forced.until)return forced.mode;if(forced)forced=null;if(!running||matchMedia('(prefers-reduced-motion: reduce)').matches)return 'chase';if(leaderId!==null&&leaderId!==leader?.p.id&&t-lastShot>7000){shotUntil=t+3300;lastShot=t}if(fast&&t-lastShot>13000){shotUntil=t+2800;lastShot=t}if(t<shotUntil)return 'front';const cycle=elapsed%25;return cycle<9?'chase':cycle<14?'front':cycle<19?'overhead':'corner'}
 function draw(t){requestAnimationFrame(draw);if(!state||!renderer)return;resize();const dt=Math.min(.06,Math.max(.001,(t-last)/1000||.016));last=t;const now=Date.now()+(window.__raceServerOffset||0),elapsed=Math.max(0,(now-state.startsAt)/1000),running=state.settings.running&&!state.settings.paused&&state.winner===null&&now>=state.startsAt,ranked=state.slots.slice(0,state.settings.cars).map((p,i)=>({p,i})).filter(x=>x.p).sort((a,b)=>b.p.distance-a.p.distance||a.i-b.i),leader=ranked[0];let speed=0,fast=false;
  for(const p of players){const driver=state.slots[p.index];if(!driver)continue;const distance=driver.distance||0;if(p.distance===null||p.round!==state.round){p.distance=distance;p.round=state.round}const before=p.distance;p.distance+=(distance-p.distance)*(1-Math.exp(-dt*10));const velocity=Math.max(0,(p.distance-before)/dt);p.velocity+=(velocity-p.velocity)*(1-Math.exp(-dt*4));speed=Math.max(speed,p.velocity);if(velocity>28)fast=true}
  if(running)scroll+=dt*(14+Math.min(38,speed*.45));curvePhase=scroll*.006;
  for(const s of strips){const a=s.mesh.geometry.attributes.position;for(let j=0;j<=60;j++){const z=-105+j*3.5,c=centerAt(z);a.setXYZ(j*2,c+s.offset-s.width/2,s.y,z);a.setXYZ(j*2+1,c+s.offset+s.width/2,s.y,z)}a.needsUpdate=true;s.mesh.geometry.computeVertexNormals()}
  for(const stream of streams){for(let i=0;i<stream.records.length;i++){const p=stream.records[i],z=((p.z+scroll+90)%180)-90;dummy.position.set(centerAt(z)+p.x,p.y,z);dummy.rotation.set(0,Math.atan(slopeAt(z)),0);dummy.scale.set(...p.scale);dummy.updateMatrix();stream.mesh.setMatrixAt(i,dummy.matrix)}stream.mesh.instanceMatrix.needsUpdate=true}
  const leadDistance=Math.max(0,...players.filter(p=>state.slots[p.index]).map(p=>p.distance||0));let packZ=0,count=0;
  for(const [i,p]of players.entries()){const driver=state.slots[i];if(!driver)continue;const gap=Math.max(0,leadDistance-p.distance),z=Math.min(9,Math.log1p(gap/state.settings.step)*1.8);p.group.position.set(centerAt(z)+(i-(state.settings.cars-1)/2)*3.2,running?Math.sin(t*.026+i)*.012:0,z);p.group.rotation.y=Math.atan(slopeAt(z));p.group.rotation.z=-slopeAt(z)*.055;for(const tire of p.tires)tire.rotation.x-=running?dt*(8+p.velocity*.7):0;p.label.classList.toggle('is-leader',leader?.i===i);packZ+=z;count++}
  packZ/=Math.max(1,count);mode=chooseCamera(elapsed,running,t,leader,fast);leaderId=leader?.p.id;const target=shots[mode],blend=1-Math.exp(-dt*3);let delta=((target.angle-orbit.angle+Math.PI*3)%(Math.PI*2))-Math.PI;orbit.angle+=delta*blend;orbit.height+=(target.height-orbit.height)*blend;const fit=Math.max(target.radius,roadWidth/(2*Math.tan(THREE.MathUtils.degToRad(24))*camera.aspect)*1.13);orbit.radius+=(fit-orbit.radius)*blend;look.set(centerAt(packZ),.6,packZ);eye.set(look.x+Math.sin(orbit.angle)*orbit.radius,orbit.height,look.z+Math.cos(orbit.angle)*orbit.radius);camera.position.copy(eye);camera.lookAt(look);camera.updateMatrixWorld();
  const remaining=Math.max(0,state.settings.length-(leader?.p.distance||0)),finishZ=-Math.min(90,remaining/12);finish.position.set(centerAt(finishZ),0,finishZ);finish.rotation.y=Math.atan(slopeAt(finishZ));
  for(const p of players){if(!state.slots[p.index])continue;point.set(p.group.position.x,1.75,p.group.position.z+.1).project(camera);p.label.style.transform='translate(-50%,-50%)';p.label.style.left=(point.x*.5+.5)*root.clientWidth+'px';p.label.style.top=(-point.y*.5+.5)*root.clientHeight+'px'}
  leaderHud.textContent=leader?'P1 · '+leader.p.name:'READY';viewHud.textContent=mode.toUpperCase();renderer.render(scene,camera);
 }
 function screenBounds(i){const p=players[i];if(!p||!camera)return null;const b=new THREE.Box3().setFromObject(p.group),points=[];for(const x of [b.min.x,b.max.x])for(const y of [b.min.y,b.max.y])for(const z of [b.min.z,b.max.z]){const q=new THREE.Vector3(x,y,z).project(camera);points.push({x:(q.x*.5+.5)*root.clientWidth,y:(-.5*q.y+.5)*root.clientHeight})}return {width:Math.max(...points.map(p=>p.x))-Math.min(...points.map(p=>p.x)),height:Math.max(...points.map(p=>p.y))-Math.min(...points.map(p=>p.y))}}
 window.Race3D={update,resize,get renderer(){return renderer},get players(){return players},get cameraMode(){return mode},get curve(){return slopeAt(0)},setCamera(mode,seconds=5){if(shots[mode])forced={mode,until:performance.now()+seconds*1000}},screenBounds};window.addEventListener('resize',resize);
})();
